from __future__ import annotations


PORTAL_HTML = r"""<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>RK3588 报告中心</title>
<style>
:root{--ink:#17242b;--muted:#66747c;--line:#d8e0e3;--blue:#087e8b;--blue2:#05616b;--red:#bc3f3f;--amber:#b26b00;--bg:#f4f7f8}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 "Microsoft YaHei",Arial,sans-serif}button,input,select,textarea{font:inherit}.top{height:58px;background:#17333b;color:#fff;display:flex;align-items:center;padding:0 22px;gap:20px}.top h1{font-size:18px;margin:0}.top .spacer{flex:1}.shell{display:grid;grid-template-columns:190px minmax(0,1fr);min-height:calc(100vh - 58px)}nav{background:#fff;border-right:1px solid var(--line);padding:12px 0}nav button{display:block;width:100%;height:42px;border:0;background:none;text-align:left;padding:0 22px;color:#40515a;cursor:pointer}nav button.active{color:var(--blue);background:#e9f4f5;border-right:3px solid var(--blue);font-weight:700}main{padding:22px;min-width:0}.page{display:none}.page.active{display:block}.head{display:flex;align-items:center;margin-bottom:16px}.head h2{font-size:20px;margin:0}.head .actions{margin-left:auto;display:flex;gap:8px}.band{background:#fff;border:1px solid var(--line);border-radius:5px;margin-bottom:14px}.band-title{padding:12px 16px;border-bottom:1px solid var(--line);font-weight:700}.band-body{padding:16px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:5px;overflow:hidden;margin-bottom:14px}.metric{background:#fff;padding:15px}.metric b{display:block;font-size:24px}.muted{color:var(--muted)}.ok{color:var(--blue)}.warn{color:var(--amber)}.bad{color:var(--red)}button.primary,button.ghost,button.danger{height:34px;padding:0 14px;border-radius:4px;cursor:pointer}button.primary{border:1px solid var(--blue);background:var(--blue);color:#fff}button.primary:hover{background:var(--blue2)}button.ghost{border:1px solid #bcc8cd;background:#fff;color:var(--ink)}button.danger{border:1px solid #dc9696;background:#fff;color:var(--red)}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:10px 12px;border-bottom:1px solid #e5eaec;text-align:left;vertical-align:top}th{color:#506069;background:#f8fafb;font-weight:600;white-space:nowrap}.filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}.filters input,.filters select,.form input,.form select,.form textarea{height:36px;border:1px solid #bdc8cd;border-radius:4px;padding:0 10px;background:#fff}.form textarea{height:120px;padding:10px;resize:vertical}.form{display:grid;grid-template-columns:170px minmax(220px,720px);gap:12px;align-items:center}.form label{font-weight:600}.form .wide{grid-column:2}.tag{display:inline-block;padding:2px 7px;border-radius:3px;background:#eef3f4;color:#40515a;font-size:12px}.empty{padding:32px;text-align:center;color:var(--muted)}#login{position:fixed;inset:0;background:#eef3f4;display:grid;place-items:center;z-index:20}#login form{width:min(390px,calc(100% - 32px));background:#fff;border:1px solid var(--line);border-radius:5px;padding:30px}#login h2{margin:0 0 6px}#login input{width:100%;height:40px;border:1px solid #bdc8cd;border-radius:4px;padding:0 10px;margin:6px 0 12px}.toast{position:fixed;right:20px;bottom:20px;padding:11px 16px;background:#17333b;color:#fff;border-radius:4px;display:none;z-index:30}.toast.bad{background:var(--red);color:#fff}@media(max-width:850px){.shell{grid-template-columns:1fr}nav{display:flex;overflow:auto;border-right:0;border-bottom:1px solid var(--line);padding:0}nav button{width:auto;min-width:max-content}.metrics{grid-template-columns:repeat(2,1fr)}main{padding:14px}.form{grid-template-columns:1fr}.form .wide{grid-column:1}.top{padding:0 14px}}
</style>
</head>
<body>
<header class="top"><h1>RK3588 患者录入与报告中心</h1><span id="mode" class="tag">读取状态</span><span class="spacer"></span><span id="who"></span><button class="ghost" id="logout">退出</button></header>
<div class="shell"><nav id="nav"><button data-page="dashboard" class="active">工作台</button><button data-page="queue">患者队列</button><button data-page="reports">报告中心</button><button data-page="profiles">设备配置档</button><button data-page="connectors">连接器与上传</button><button data-page="system">系统管理</button></nav>
<main>
<section id="dashboard" class="page active"><div class="head"><h2>工作台</h2><div class="actions"><button class="ghost" onclick="loadStatus()">刷新</button></div></div><div class="metrics" id="metrics"></div><div class="band"><div class="band-title">当前患者与硬件</div><div class="band-body" id="hardware"></div></div></section>
<section id="queue" class="page"><div class="head"><h2>患者队列</h2><div class="actions"><button class="primary" onclick="manualIntake()">人工添加</button><button class="ghost" onclick="loadSessions()">刷新</button></div></div><div class="band"><table><thead><tr><th>时间</th><th>患者</th><th>检查项目</th><th>来源</th><th>状态</th><th>操作</th></tr></thead><tbody id="sessionRows"></tbody></table></div></section>
<section id="reports" class="page"><div class="head"><h2>报告中心</h2><div class="actions"><button class="ghost" onclick="loadReports()">刷新</button></div></div><div class="filters"><input id="rName" placeholder="患者姓名"><input id="rPatient" placeholder="患者ID"><input id="rExam" placeholder="检查号"><select id="rStatus"><option value="">全部归档状态</option><option>archived</option><option>review_required</option><option>invalid</option><option>purged</option></select><button class="primary" onclick="loadReports()">查询</button></div><div class="band"><table><thead><tr><th>归档时间</th><th>患者</th><th>检查项目</th><th>来源</th><th>归档</th><th>上传</th><th>操作</th></tr></thead><tbody id="reportRows"></tbody></table></div></section>
<section id="profiles" class="page"><div class="head"><h2>设备配置档</h2><div class="actions"><button class="ghost" onclick="loadProfiles()">刷新</button><button class="primary" onclick="newProfile()">新建配置档</button></div></div><div class="band"><table><thead><tr><th>名称</th><th>版本</th><th>患者模式</th><th>报告来源</th><th>状态</th><th>操作</th></tr></thead><tbody id="profileRows"></tbody></table></div><div class="band"><div class="band-title">草稿编辑</div><div class="band-body form"><label>配置 JSON</label><textarea class="wide" id="profileJson"></textarea><span></span><div><button class="ghost" onclick="testProfile()">测试</button> <button class="primary" onclick="saveProfile()">保存草稿</button> <button class="primary" onclick="publishProfile()">发布</button></div></div></div></section>
<section id="connectors" class="page"><div class="head"><h2>连接器与上传</h2><div class="actions"><button class="primary" onclick="newConnector()">新建</button><button class="ghost" onclick="loadConnectors()">刷新</button></div></div><div class="band"><table><thead><tr><th>名称</th><th>类型</th><th>地址</th><th>状态</th><th>操作</th></tr></thead><tbody id="connectorRows"></tbody></table></div></section>
<section id="system" class="page"><div class="head"><h2>系统管理</h2></div><div class="band"><div class="band-title">存储清理</div><div class="band-body form"><label>本地保留天数</label><input id="retention" type="number" min="1" value="90"><span></span><div><button class="ghost" onclick="cleanup(false)">清理预览</button> <button class="danger" onclick="cleanup(true)">确认清理</button></div><label>结果</label><pre id="cleanupResult"></pre></div></div><div class="band"><div class="band-title">审计日志</div><div class="band-body"><button class="ghost" onclick="loadAudit()">加载审计日志</button><pre id="auditResult"></pre></div></div></section>
</main></div>
<div id="login"><form id="loginForm"><h2>报告中心登录</h2><p class="muted">使用管理员或操作员账号</p><label>用户名</label><input id="username" value="admin" autocomplete="username"><label>密码</label><input id="password" type="password" autocomplete="current-password"><button class="primary" style="width:100%;margin-top:8px">登录</button><p id="loginError" class="bad"></p></form></div><div id="toast" class="toast"></div>
<script>
let csrf='',role='',selectedProfile=0;const $=id=>document.getElementById(id);function toast(msg,bad=false){const e=$('toast');e.textContent=msg;e.className='toast'+(bad?' bad':'');e.style.display='block';setTimeout(()=>e.style.display='none',2800)}async function api(path,opts={}){opts.headers={...(opts.headers||{})};if(opts.body&&!opts.headers['Content-Type'])opts.headers['Content-Type']='application/json';if(!['GET','HEAD'].includes((opts.method||'GET').toUpperCase()))opts.headers['X-CSRF-Token']=csrf;const r=await fetch(path,opts);if(r.status===401){$('login').style.display='grid';throw Error('请先登录')}if(!r.ok){let d={};try{d=await r.json()}catch{}throw Error(d.error||('HTTP '+r.status))}return r.status===204?{}:r.json()}
$('loginForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/v1/auth/login',{method:'POST',body:JSON.stringify({username:$('username').value,password:$('password').value})});csrf=d.csrf;role=d.role;$('who').textContent=d.username+' · '+d.role;$('login').style.display='none';boot()}catch(err){$('loginError').textContent=err.message}};$('logout').onclick=async()=>{try{await api('/api/v1/auth/logout',{method:'POST',body:'{}'})}finally{location.reload()}};
document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('#nav button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===b.dataset.page));({queue:loadSessions,reports:loadReports,profiles:loadProfiles,connectors:loadConnectors,system:()=>{}}[b.dataset.page]||(()=>{}))()});
function statusTag(v){return '<span class="tag">'+String(v||'-')+'</span>'}async function loadStatus(){const d=await api('/api/v1/status');$('mode').textContent=d.shadow_mode?'影子模式':'正式运行';const c=d.counts;$('metrics').innerHTML=`<div class="metric"><span class="muted">排队患者</span><b>${c.sessions.queued||0}</b></div><div class="metric"><span class="muted">等待报告</span><b>${c.sessions.awaiting_report||0}</b></div><div class="metric"><span class="muted">已归档报告</span><b>${c.reports.archived||0}</b></div><div class="metric"><span class="muted">待上传</span><b>${(c.uploads.pending||0)+(c.uploads.retry_wait||0)}</b></div>`;const h=await api('/api/v1/hardware');$('hardware').innerHTML='<pre>'+escapeHtml(JSON.stringify(h,null,2))+'</pre>'}async function loadSessions(){const d=await api('/api/v1/sessions');$('sessionRows').innerHTML=d.items.map(s=>`<tr><td>${fmt(s.created_at)}</td><td>${esc(s.patient_name||'待复核')}<br><span class="muted">${esc(s.patient_id||'')}</span></td><td>${esc(s.exam_item||'')}</td><td>${esc(s.source)}</td><td>${statusTag(s.status)}</td><td><button class="ghost" onclick="sessionAction('${s.id}','cancel')">取消</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">暂无患者</td></tr>'}async function sessionAction(id,action){try{await api(`/api/v1/sessions/${id}/${action}`,{method:'POST',body:'{}'});loadSessions()}catch(e){toast(e.message,true)}}async function manualIntake(){const name=prompt('患者姓名');if(!name)return;const patientId=prompt('患者ID（可留空）')||'';await api('/api/v1/intake',{method:'POST',body:JSON.stringify({mode:'manual',patient:{patient_name:name,patient_id:patientId}})});loadSessions()}
async function loadReports(){const q=new URLSearchParams({patient_name:$('rName').value,patient_id:$('rPatient').value,his_exam_no:$('rExam').value,status:$('rStatus').value});const d=await api('/api/v1/reports?'+q);$('reportRows').innerHTML=d.items.map(r=>`<tr><td>${fmt(r.archived_at||r.created_at)}</td><td>${esc(r.patient_name||'未关联')}<br><span class="muted">${esc(r.patient_identifier||'')}</span></td><td>${esc(r.exam_item||'')}</td><td>${esc(r.source)}</td><td>${statusTag(r.status)}</td><td>${statusTag(r.upload_status||'未配置')}</td><td><a href="/api/v1/reports/${r.id}/content" target="_blank">预览</a> <button class="ghost" onclick="retryUpload(${r.id})">重试上传</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">暂无报告</td></tr>'}async function retryUpload(id){try{await api(`/api/v1/reports/${id}/retry-upload`,{method:'POST',body:'{}'});toast('已加入重试')}catch(e){toast(e.message,true)}}
async function loadProfiles(){const d=await api('/api/v1/profiles');$('profileRows').innerHTML=d.items.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.version||'-'}</td><td>${esc((p.config||{}).patient_input_mode||'')}</td><td>${esc((p.config||{}).report_source||'')}</td><td>${p.active?statusTag('当前'):'-'}</td><td><button class="ghost" onclick="editProfile(${p.id})">编辑</button></td></tr>`).join('')}async function editProfile(id){selectedProfile=id;const d=await api('/api/v1/profiles/'+id);const rev=d.revisions.find(x=>x.status==='draft')||d.revisions[0];$('profileJson').value=JSON.stringify(rev.config,null,2)}async function newProfile(){const name=prompt('配置档名称');if(!name)return;const d=await api('/api/v1/profiles',{method:'POST',body:JSON.stringify({name,config:{patient_input_mode:'manual',patient_connector_id:null,exam_item_filter:'',auto_entry_enabled:false,report_source:'msc',field_resolver:{provider:'rules',fields:[]},hid:{template_path:'',actions:[]},upload_target_id:null}})});selectedProfile=d.id;await editProfile(d.id);loadProfiles()}async function saveProfile(){if(!selectedProfile)return toast('请先选择配置档',true);try{await api(`/api/v1/profiles/${selectedProfile}/draft`,{method:'PUT',body:JSON.stringify({config:JSON.parse($('profileJson').value)})});toast('草稿已保存');loadProfiles()}catch(e){toast(e.message,true)}}async function testProfile(){try{const d=await api(`/api/v1/profiles/${selectedProfile}/test`,{method:'POST',body:JSON.stringify({config:JSON.parse($('profileJson').value)})});toast(d.ok?'配置测试通过':'配置测试失败',!d.ok)}catch(e){toast(e.message,true)}}async function publishProfile(){try{await saveProfile();await api(`/api/v1/profiles/${selectedProfile}/publish`,{method:'POST',body:'{}'});toast('配置已发布');loadProfiles()}catch(e){toast(e.message,true)}}
async function loadConnectors(){const d=await api('/api/v1/connectors');$('connectorRows').innerHTML=d.items.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.type)}</td><td>${esc((c.config||{}).endpoint||'')}</td><td>${statusTag(c.enabled?'启用':'停用')}</td><td><button class="ghost" onclick="testConnector(${c.id})">连接测试</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">暂无连接器</td></tr>'}async function newConnector(){const name=prompt('连接器名称');if(!name)return;const type=prompt('类型：sql_proxy / rest_json / report_multipart / rest_multipart','rest_json');const endpoint=prompt('接口地址','http://');await api('/api/v1/connectors',{method:'POST',body:JSON.stringify({name,type,config:{endpoint,method:'POST',request:{code:'{{query}}'},records_path:'$.data',field_mapping:{}}})});loadConnectors()}async function testConnector(id){const q=prompt('输入脱敏测试号码');if(!q)return;try{const d=await api(`/api/v1/connectors/${id}/test`,{method:'POST',body:JSON.stringify({query:q})});toast(`成功，${d.record_count||0} 条记录`)}catch(e){toast(e.message,true)}}
async function cleanup(execute){if(execute&&!confirm('只会删除已上传成功且超过保留期的 PDF，确认执行？'))return;const d=await api('/api/v1/maintenance/cleanup',{method:'POST',body:JSON.stringify({retention_days:+$('retention').value,execute})});$('cleanupResult').textContent=JSON.stringify(d,null,2)}async function loadAudit(){const d=await api('/api/v1/audit');$('auditResult').textContent=JSON.stringify(d.items,null,2)}function fmt(v){return v?new Date(v*1000).toLocaleString():'-'}function esc(v){return escapeHtml(String(v??''))}function escapeHtml(v){return v.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}async function boot(){await Promise.all([loadStatus(),loadSessions()]).catch(e=>toast(e.message,true))}fetch('/api/v1/auth/session').then(r=>r.ok?r.json():Promise.reject()).then(d=>{csrf=d.csrf;role=d.role;$('who').textContent=d.username+' · '+d.role;$('login').style.display='none';boot()}).catch(()=>{});
</script></body></html>"""
